SourceCode.Declaration:
/// <summary>
/// Represent one row in GupPriceMarginComponentSetup, i.e. one margin component set as [in-use].
/// Each margin component code contains multiple [header attribute groups]. Each header then have multiple [line attribute groups].
/// The header + line combination (and priority for each component code) are created in margin component code setup.
/// </summary>
internal class GUPPriceEngineMarginComponent
{
    // Basic Setup information.
    GupPriceMarginComponentSetup marginComponentSetup;

    // List of GUPPriceEngineMarginCodeLineAggregation, provided that percentListLength > 0.
    // Sorted by [attribute group priority] descending, then by [lowestPercentage] aescending. 
    // [Null] if no lines belong to this type.
    private List percentageAggregationList;

    // List of GUPPriceEngineMarginCodeLineAggregation, provided that fixedAmountListLength > 0.
    // Sorted by [attribute group priority] descending, then by [lowestFixedAmount] aescending.
    // [Null] if no lines belong to this type.
    private List fixedAmountAggregationList;

}

Method.Source:
    public void new(GupPriceMarginComponentSetup _marginComponentSetup, 
        List _percentageAggregationList,
        List _fixedAmountAggregationList)
    {
        this.marginComponentSetup = _marginComponentSetup.data();
        this.percentageAggregationList = _percentageAggregationList;
        this.fixedAmountAggregationList = _fixedAmountAggregationList;

        this.sortAggregationLists();
    }

    private void sortAggregationLists()
    {
        if (percentageAggregationList != null)
        {
            GUPListSorter listSorter = GUPListSorter::getInstance();
            GUPComparatorMarginCodeLineAggregationPercentage lineComparator = new GUPComparatorMarginCodeLineAggregationPercentage();
            this.percentageAggregationList = listSorter.sortList(this.percentageAggregationList, lineComparator);
        }

        if (fixedAmountAggregationList != null)
        {
            GUPListSorter listSorter = GUPListSorter::getInstance();
            GUPComparatorMarginCodeLineAggregationFixedAmount lineComparator = new GUPComparatorMarginCodeLineAggregationFixedAmount();
            this.fixedAmountAggregationList = listSorter.sortList(this.fixedAmountAggregationList, lineComparator);
        }

    }
